INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_PUBLIC_TRANSPORT',			'대중교통'),
		('TXT_KEY_BUILDING_PUBLIC_TRANSPORT_TEXT',		'대중교통의 예로는 시내버스, 트롤리버스, 트램(또는 경전철) 및 여객 열차, 고속철도(지하철 등) 및 페리가 있습니다. 1826년에 낭트에서 버스가 운행된 것으로 알려져 있는데, 이는 1863년 런던에서 세계 최초의 증기 기관차 지하철이 개통되기 얼마 전이었습니다. 오늘날 통근 열차, 지하철, 버스(그리고 트램)는 세계 대도시 중심지에 필수적인 인프라입니다. 매일 런던으로 출퇴근하는 100만 명이 넘는 사람 중 80%가 대중교통을 이용합니다. 대중교통을 이용하면 개인 교통수단에 비해 배출량과 기타 환경 영향이 줄어들기 때문에 많은 전문가는 대중교통에 대한 투자를 늘리는 것이 기후 변화 완화에 중요한 전략이라고 지적했습니다.'),
		('TXT_KEY_BUILDING_PUBLIC_TRANSPORT_STRATEGY',	'기업형 농장은 군사적으로 쓸모없어진 말을 필요로 하지만, 대중 교통은 여전히 유닛 생산에 중요한 철을 필요로 합니다. 따라서 게임 후반에 등장하는 건물 건설은 성장 기반 수익을 가장 잘 활용할 수 있는 도시에만 신중하게 배분해야 합니다. 탐욕스러울수록 더 많이 가질 수 있어요!'),
		('TXT_KEY_BUILDING_PUBLIC_TRANSPORT_HELP',		'Gain 20% of the output of [COLOR_POSITIVE_TEXT]All Yields[ENDCOLOR] in the City as an instant boost when a [ICON_CITIZEN] Citizen is born in this City. +10 [ICON_FOOD] Food if the City has a [COLOR_POSITIVE_TEXT]Power Plant[ENDCOLOR].[NEWLINE][NEWLINE]-1 [ICON_HAPPINESS_3] Unhappiness from [ICON_GOLD] Poverty.[NEWLINE][NEWLINE]Requires 2 [ICON_RES_IRON] Iron and an [ICON_INDUSTRIAL_CONNECTED] Industrial City Connection.');